  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "Общайтесь с выбранной моделью; {mnemo} читает, пишет, тегирует, связывает, перемещает и упорядочивает заметки инструментами Memora. Он не может искать в интернете, запускать команды, удалять навсегда или менять сервер. Ключи хранятся зашифрованными на этом сервере и никогда не уходят в браузер.",
