  "Choose from many languages in Settings, Appearance, per device. Auto follows your browser.": "Выберите один из многих языков в Настройках, Внешний вид, для каждого устройства. «Авто» следует языку браузера.",
  "Choose your vault folder": "Выберите папку хранилища",
