  "Claude Desktop (older)": "Claude Desktop (старая версия)",
  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude и ChatGPT входят через ваш аккаунт Memora. Копировать ничего не нужно.",
  "Claude models": "Модели Claude",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude входит через OAuth, поэтому ключ вставлять не нужно: он получит свой ключ, когда вы нажмёте «Разрешить». Без входа подключите его как <b>Другое приложение</b> и отправляйте заголовок <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor и другие",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor и другие, у каждого свой ключ",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "Claude, ChatGPT, Cursor, Codex и другие получают свой доступ, так что видно, что делает каждый.",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Claude, Cursor, ChatGPT и ваш собственный агент делят одну Memora, доступную с этого компьютера, из локальной сети или из интернета",
