  "Download the file": "Скачать файл",
  "Download the {kind} file": "Скачать файл: {kind}",
  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "Перетащите карточку в рамку другой папки, чтобы переместить заметку на диске. Перетаскивайте рамку за название, чтобы переставить доску; бросьте её на другую рамку, чтобы переместить туда всю папку. Дважды нажмите на заголовок, чтобы переименовать. На сенсорном экране: перетаскивание сдвигает, щипок масштабирует, долгое нажатие на карточку перемещает её, касание открывает просмотр.",
  "Drag a note here to pin it": "Перетащите заметку сюда, чтобы закрепить",
  "Drag notes or folders here to pin them": "Перетащите заметки или папки сюда, чтобы закрепить",
  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "Перетащите заметки или папки на папку, чтобы переместить, или на «Закреплённые», чтобы закрепить.",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "Перетаскивайте заметки · двойной щелчок закрепляет · / поиск · #тег ищет теги · F вписать · 1 2 3 раскладки",
  "Drag to move the folder frame; double-click to rename": "Перетащите, чтобы переместить рамку папки; двойной щелчок переименует",
  "Drag to move the lane. Double click the name to rename it.": "Перетащи, чтобы переместить колонку. Дважды щёлкни по названию, чтобы переименовать.",
  "Drag to resize · double-click to reset": "Перетащите, чтобы изменить размер · двойной щелчок сбросит",
  "Drag to turn · scroll to zoom · click a point to open its note": "Перетащите, чтобы повернуть · прокрутите для масштаба · нажмите на точку, чтобы открыть заметку",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "Перетащите, чтобы повернуть · прокрутите для масштаба · нажмите на точку, чтобы открыть заметку · / поиск · #тег ищет теги",
  "Draw a chart of how many notes I write each week": "Нарисуй график того, сколько заметок я пишу каждую неделю",
  "Draw this note as a diagram": "Нарисуй эту заметку в виде схемы",
  "Drop a card here or add one": "Перетащите карточку сюда или добавьте новую",
  "Drop here to hide": "Бросьте сюда, чтобы скрыть",
  "Drop on a folder": "Бросьте на папку",
  "Due": "Срок",
  "Due date": "Срок",
  "Due date: red when late, amber when soon, green later.": "Срок: красный, если просрочен, янтарный, если скоро, зелёный, если позже.",
  "Duplicate": "Дублировать",
  "Duplicate board": "Дублировать доску",
  "Duplicate lane": "Дублировать колонку",
  "Duplicated a note": "Дублировал заметку",
