  "Dusk": "Сумерки",
  "Dyslexic": "Для дислексии",
  "Each AI app connects over MCP with its own key and permissions.": "Каждое ИИ-приложение подключается через MCP со своим ключом и своими правами.",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "Каждое подключённое ИИ-приложение — это агент со своим ключом, так что видно, что делает каждое, и можно отключить одно отдельно.",
  "Each agent": "Каждый агент",
  "Each agent belongs to one app. For another app or device, make a new agent.": "Каждый агент принадлежит одному приложению. Для другого приложения или устройства создайте нового агента.",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "Каждый агент принадлежит одному приложению. Чтобы использовать Memora в другом приложении, создайте для него отдельного агента.",
  "Each app gets its own key": "У каждого приложения свой ключ",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "У каждого короткий ID, который никогда не меняется, поэтому имена можно менять свободно. Mnemo создаёт их, меняет указания или модель, пишет им, ждёт, останавливает, завершает и удаляет — по одному или всех сразу — и может пустить их работать в фоне. На каждой карточке видны Задание, Активность и Ответ.",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "Каждый вид измеряется по своему пространству: по его лимиту, если он задан, иначе по занятому плюс свободное место на диске{disk}. Пустой лимит: без ограничения.",
  "Each one gets its own key from Memora.": "Каждый получает от Memora собственный ключ.",
