  "Embed new or existing boards in a note and work on each right there, or put a board into any note from its ⋯ menu; a plain link reads as a small card.": "Встраивайте новые или существующие доски в заметку и работайте с каждой прямо там или вставьте доску в любую заметку через её меню ⋯; обычная ссылка выглядит как маленькая карточка.",
