  "Everything it did": "Всё, что он сделал",
  "Everything it did, and who it was for": "Всё, что он сделал, и для кого",
  "Everything shown is already off.": "Всё показанное уже выключено.",
  "Everything shown is already on.": "Всё показанное уже включено.",
