  "Everything {name} did, newest first": "Всё, что сделал {name}, сначала новое",
  "Everything, plus switching tools off for everyone and managing other agents. Only for automation you fully trust.": "Всё, плюс отключение инструментов для всех и управление другими агентами. Только для автоматизации, которой вы полностью доверяете.",
