  "Folder names floating over the part of the brain that holds their notes.": "Названия папок парят над той частью мозга, где лежат их заметки.",
  "Folder names: the point of each folder and the title over the area its notes fill.": "Названия папок: точка каждой папки и заголовок над областью её заметок.",
