  "Folders: show or hide them": "Папки: показать или скрыть",
  "Follow links between notes: neighbours, paths, hubs and loose ends.": "Следуйте по ссылкам между заметками: соседи, пути, центры и висячие концы.",
  "Follow the app theme": "Как тема приложения",
  "Follow the {app} setup guide to connect it.": "Следуйте руководству по настройке {app}, чтобы подключить его.",
  "Follow-up": "Уточнение",
  "Follows your browser": "Как в браузере",
  "Font": "Шрифт",
  "For": "Для",
  "For authentication choose <b>OAuth</b>, leave the client ID and secret empty, and click <b>Create</b>. A Memora page opens: press <b>Allow</b>.": "В качестве аутентификации выберите <b>OAuth</b>, оставьте ID клиента и секрет пустыми и нажмите <b>Create</b>. Откроется страница Memora: нажмите <b>Разрешить</b>.",
  "For example: Product launch": "Например: Запуск продукта",
  "For example: Review": "Например: Проверка",
  "For links, checkboxes and quotes. None uses the page colour’s own.": "Для ссылок, флажков и цитат. При «Нет» используется цвет, заданный цветом страницы.",
  "For you": "Для вас",
  "For {name}": "Для {name}",
  "Force": "Force",
  "Force: linked notes pull together and the rest push apart, so clusters form by themselves.": "Force: связанные заметки притягиваются, остальные отталкиваются, так что кластеры образуются сами.",
  "Forest": "Лес",
  "Forgot password or need help?": "Забыли пароль или нужна помощь?",
  "Forgot something about you": "Забыл кое-что о вас",
  "Forgotten": "Забыто",
  "Formatting": "Форматирование",
  "Found follow-ups": "Нашёл задачи для продолжения",
  "Found hub notes": "Нашёл центральные заметки",
  "Found similar notes": "Нашёл похожие заметки",
