  "Friday": "Пятница",
  "From": "От",
  "From a note: {tip}": "Из заметки: {tip}",
  "From anywhere": "Откуда угодно",
  "From now on, whenever I tell you something important, save it into Memora. Try it now: save a note that I started using Memora today.": "Отныне, когда я говорю тебе что-то важное, сохраняй это в Memora. Попробуй сейчас: сохрани заметку о том, что сегодня я начал пользоваться Memora.",
  "From the note {path}": "Из заметки {path}",
  "From {file}": "Из {file}",
  "Full": "Полный",
  "Full changelog": "Полный список изменений",
  "Full control": "Полный контроль",
  "Full prompt": "Полный запрос",
  "Full screen": "Во весь экран",
  "GPT models": "Модели GPT",
  "Gateway": "Шлюз",
  "Gathered to-dos": "Собрал задачи",
  "Gathering the real activity for {range}. This can take a moment on a big log, please wait.": "Собираем реальную активность за период: {range}. В большом журнале это может занять время, подождите.",
  "General": "Общие",
  "Get a one-time code on the server": "Получить одноразовый код на сервере",
  "Get started": "Начать",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "Узнай меня по моим заметкам. Просмотри моё хранилище (недавние заметки, дневники, проекты, всё обо мне) и сохрани узнанное через remember_owner: кто я, над чем работаю, какие ответы люблю, что мне нравится. Только короткое и долговечное, никаких секретов. Затем в паре строк расскажи, что сохранил.",
  "Gets its own agent key: read and write nodes over MCP": "Получает свой ключ агента: чтение и запись узлов через MCP",
  "Getting started": "Начало работы",
  "GitHub answered HTTP {code}": "GitHub ответил HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Дайте Claude, Cursor или любому приложению с MCP свой ключ, а затем пусть оно сохранит то, что уже знает о вас.",
  "Give a key read-only access, or let it write too.": "Дайте ключу доступ только на чтение или разрешите и запись.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "Заведите для каждого приложения или устройства своего агента. Тогда Активность покажет, кто что делал, а одного можно отключить, не трогая остальных.",
  "Give it a name you recognise": "Дайте ему понятное имя",
  "Give the agent a name": "Назовите агента",
  "Give the provider a name": "Назовите провайдера",
  "Give the tag a name: letters, digits and - _ / . only.": "Задайте тегу имя: только буквы, цифры и - _ / .",
  "Glow": "Свечение",
