  "Lanes are the columns of the board, such as To do, Doing and Done.": "Колонки — это столбцы доски, например «Сделать», «В работе» и «Готово».",
  "Lanes fade at the edge while there is more to see, snap one at a time on phones with dots to jump between them, and links, tags and mentions on cards show as chips.": "Колонки затухают у края, пока есть что посмотреть, на телефонах листаются по одной, а точки помогают переходить между ними; ссылки, теги и упоминания на карточках показываются как чипы.",
