  "Locks, mentions and assignments so agents do not overwrite each other.": "Блокировки, упоминания и назначения, чтобы агенты не перезаписывали друг друга.",
  "Long chats, light": "Длинные чаты — легко",
  "Long enough. A few more characters make it stronger.": "Достаточно длинный. Ещё несколько символов сделают его надёжнее.",
  "Longer tasks show as a checklist above the message box: not started, in progress, done.": "Длинные задачи показываются списком над полем сообщения: не начато, в работе, готово.",
  "Longest sign-in": "Макс. срок входа",
