  "Look for tags that mean the same thing": "Найти теги с одинаковым смыслом",
  "Look through the project in this folder and save it into Memora: what it is for, how it is built, how to run it, technical decisions, and anything worth remembering. Make one note per topic, in a folder named after the project inside Projects.": "Изучи проект в этой папке и сохрани его в Memora: для чего он, как устроен, как запускать, технические решения и всё, что стоит запомнить. Сделай по одной заметке на тему, в папке с названием проекта внутри Projects.",
