  "Measuring…": "Измеряем…",
  "Medium": "Средний",
  "Medium text": "Средний текст",
  "Meet Mnemo, your notes agent": "Знакомьтесь: Mnemo, ваш агент для заметок",
  "Memora address (MCP endpoint)": "Адрес Memora (конечная точка MCP)",
  "Memora already uses this folder.": "Memora уже использует эту папку.",
  "Memora by Codrihub Tech": "Memora от Codrihub Tech",
  "Memora can save notes here": "Memora может сохранять заметки здесь",
  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Memora проверяет папку и просит подтвердить, прежде чем переключиться. Ничего не перемещается и не копируется, а вернуться можно здесь же. Работаете в Docker? Используйте папку, примонтированную в контейнер.",
  "Memora could not start.": "Memora не удалось запустить.",
  "Memora data folder": "Папка данных Memora",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Сначала Memora проверит, что новая папка существует (или может быть создана) и что в неё можно сохранять заметки. Если проверка не пройдена, ничего не изменится.",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Сначала Memora проверит, что новая папка существует и что в неё можно сохранять заметки. Если проверка не пройдена, ничего не изменится.",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Memora на вашем языке, Mnemo показывает свой план по ходу работы, а вы выбираете, чем ему пользоваться и что видеть.",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Memora — приложение для заметок, которым могут пользоваться и ваши ИИ-приложения. Вы пишете в нём, они читают и пишут те же заметки, а вы всегда видите, что изменилось.",
  "Memora is free and open source": "Memora бесплатна и с открытым кодом",
  "Memora is free and open source. A star helps others find it.": "Memora бесплатна и с открытым кодом. Звезда помогает другим её найти.",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Memora — это память, но продвинутая: она создана, чтобы помнить всё, что узнаёте вы и ваш ИИ, и помнить тем больше, чем чаще вы ею пользуетесь.",
  "Memora is restarting": "Memora перезапускается",
  "Memora is shut down": "Memora выключена",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Memora пока пуста. Подключите ИИ-приложение, отправьте ему один запрос, и оно сохранит здесь то, что знает о вас, в виде заметок, которые можно читать, править и видеть в мозге.",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Memora хранит список ваших тегов, чтобы подсказывать их при вводе. Обновите его, если тега не хватает или он устарел.",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "Memora хранит каждую версию заметки, если папка хранилища — репозиторий git. Один раз выполните {cmd} в папке хранилища (см. Конфигурация, «История версий» в документации); дальше каждое изменение сохраняется здесь.",
  "Memora keeps it in one place:": "Memora хранит это в одном месте:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Memora сохраняет каждую заметку обычным файлом Markdown на машине, где работает. Ничто не заперто: открывайте файлы в любом редакторе, делайте резервные копии или храните их в Git.",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Memora работает по MCP через streamable HTTP. Приложения передают ключ в заголовке <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Memora остановится на машине, где работает. Ваши заметки в сохранности на диске.",
  "Memora version": "Версия Memora",
  "Memora v{latest} is available. This server runs v{current}.": "Доступна Memora v{latest}. На этом сервере работает v{current}.",
  "Memora, open Overview": "Memora, открыть обзор",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: хранилище заметок на вашем сервере, с агентом, который наводит в нём порядок.",
  "Memory used: {used} of {win}": "Использовано памяти: {used} из {win}",
