  "Messaged {agent}": "Сообщение для {agent}",
  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "Сообщения и поле ввода выровнены точно при любой ширине, у выбора модели своя поверхность, мимолётный чат помещается на телефоне, а варианты ответа на вопрос больше не уезжают из-под пальца.",
  "Middle-drag": "Перетаскивание средней кнопкой",
  "Midnight": "Полночь",
  "Minimap": "Миникарта",
  "Minimap: click or drag to move the view": "Миникарта: нажмите или перетащите, чтобы сместить вид",
  "Mist": "Туман",
  "Mnemo (AI agent)": "Mnemo (ИИ-агент)",
  "Mnemo and agents can do on a board everything you can, over MCP, behind four Kanban permission switches that follow Ask first, Auto and Read only.": "Mnemo и агенты могут делать на доске всё то же, что и вы, через MCP, под защитой четырёх переключателей разрешений Kanban, которые следуют режимам «Сначала спрашивать», «Авто» и «Только чтение».",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "Кнопка Mnemo скрыта. Верните её через Ещё, Показать кнопку Mnemo.",
  "Mnemo goes on without sub-agents": "Mnemo продолжит без субагентов",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "У Mnemo пока нет модели: добавьте провайдера и его модели в Настройки, Mnemo",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Mnemo встроен в Memora. Подключите свой ИИ-ключ и просите простыми словами: он найдёт, напишет, пометит тегами, свяжет и приведёт в порядок заметки.",
  "Mnemo is still answering in this chat": "Mnemo ещё отвечает в этом чате",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Mnemo — агент, встроенный в Memora. Подключите свой ключ ИИ и просите простыми словами: он поддерживает порядок в заметках, пока другие приложения ими пользуются.",
  "Mnemo keeps at most {n} providers; delete one first": "Mnemo хранит не больше {n} провайдеров; сначала удалите одного",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Mnemo управляет своими субагентами, хранит план вместе с чатом, а чат лучше смотрится на любом экране.",
  "Mnemo runs its sub-agents": "Mnemo руководит субагентами",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Mnemo остановился после {n} шагов; напишите «продолжай», чтобы идти дальше.",
  "Mnemo's plan, live": "План Mnemo в реальном времени",
  "Mnemo's question sits on its own band, its answers below as rows to tap, as many as the question needs.": "Вопрос Mnemo стоит на своей полосе, а ответы под ним — строки для нажатия, столько, сколько нужно вопросу.",
  "Mnemo, your notes agent": "Mnemo, ваш агент заметок",
