  "Not created yet · create": "Ещё не создано · создать",
  "Not created yet · create it": "Ещё не создано · создать",
  "Not created yet. Click to create it.": "Ещё не создано. Нажмите, чтобы создать.",
  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "Не выполнено: Mnemo в режиме «Сначала спрашивать», поэтому изменения ждут согласия владельца. Спросите через ask_owner (скажите, что собираетесь изменить; дайте вариант с approve: true, например «Да, продолжай»), затем вносите изменение после одобрения.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "Не выполнено: Mnemo в режиме «Только чтение», поэтому заметки не меняются. Скажите, что вы бы изменили; владелец может переключить чат на «Сначала спрашивать» или «Авто».",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "Не выполнено: чат в режиме «Сначала спрашивать», поэтому субагент не может менять заметки. Напишите в ответе, что нужно изменить; Mnemo спросит владельца.",
  "Not done: the owner switched {tool} off for Mnemo (Settings, Mnemo).": "Не выполнено: владелец отключил {tool} для Mnemo (Настройки, Mnemo).",
  "Not done: the owner switched {tool} off for sub-agents (Settings, Mnemo).": "Не выполнено: владелец отключил {tool} для субагентов (Настройки, Mnemo).",
  "Not finished: the owner cut this reply before the tool returned.": "Не завершено: владелец прервал этот ответ до того, как инструмент вернул результат.",
