  "Notes": "Заметки",
  "Notes and boards share one page frame with the same spacing on phones, tablets and desktops, and the links at the foot of a note share one tidy look that folds away.": "Заметки и доски используют одну рамку страницы с одинаковыми отступами на телефонах, планшетах и компьютерах, а ссылки внизу заметки выглядят единообразно и аккуратно и сворачиваются.",
  "Notes and boards, connected": "Заметки и доски связаны",
  "Notes and images in the notes folder.": "Заметки и изображения в папке заметок.",
  "Notes and the links between them show up here as a map. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Заметки и связи между ними показываются здесь как карта. В руководстве показано, как заставить ИИ сохранять знания сюда или как написать заметку самому.",
  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "Заметки появляются по мере того, как ИИ их сохраняет, и зажигают мозг. Когда придёт первая заметка, эта страница станет вашей панелью.",
  "Notes are not a password manager.": "Заметки — не менеджер паролей.",
  "Notes changed in the app or in the folder": "Заметки изменены в приложении или в папке",
  "Notes folder": "Папка заметок",
  "Notes folder switched": "Папка заметок переключена",
  "Notes from {name}": "Заметки от {name}",
  "Notes in the Obsidian Kanban format open as boards. Drag cards and lanes with a mouse or a finger, and every change lands in the note’s history.": "Заметки в формате Obsidian Kanban открываются как доски. Перетаскивайте карточки и колонки мышью или пальцем, и каждое изменение попадает в историю заметки.",
  "Notes in the current folder are not moved, copied or deleted. You can switch back here at any time.": "Заметки в текущей папке не перемещаются, не копируются и не удаляются. Вернуться можно здесь в любой момент.",
  "Notes inside a folder": "Заметки внутри папки",
  "Notes it found": "Найденные им заметки",
  "Notes it saved": "Сохранённые им заметки",
  "Notes must carry": "Заметки должны иметь",
  "Notes tagged #{tag}": "Заметки с тегом #{tag}",
  "Notes that carry at least one tag": "Заметки хотя бы с одним из тегов",
  "Notes that carry every tag": "Заметки со всеми тегами",
  "Notes that link nowhere and are linked from nowhere.": "Заметки, которые никуда не ссылаются и на которые никто не ссылается.",
  "Notes touched": "Затронуто заметок",
  "Notes with a tag; the start of the tag is enough": "Заметки с тегом; достаточно начала тега",
  "Notes you delete wait here, so you can bring them back.": "Удалённые заметки ждут здесь, чтобы вы могли их вернуть.",
  "Notes you or your AIs write show up here, newest first.": "Заметки, которые пишете вы или ваши ИИ, появятся здесь, сначала новые.",
  "Notes, folders and images in this chat": "Заметки, папки и изображения в этом чате",
  "Nothing deleted": "Ничего не удалено",
  "Nothing else in the last 24 hours.": "Больше ничего за последние 24 часа.",
  "Nothing from {name} in the last 24 hours.": "Ничего от {name} за последние 24 часа.",
  "Nothing here": "Здесь ничего нет",
  "Nothing hidden yet: tick the agents to hide it from. Right now all {n} agents can see it.": "Пока ничего не скрыто: отметьте агентов, от которых скрыть. Сейчас его видят все агенты ({n}).",
  "Nothing hidden yet: tick the agents to hide it from. Right now the only agent can see it.": "Пока ничего не скрыто: отметьте агентов, от которых скрыть. Сейчас его видит единственный агент.",
  "Nothing in 24h": "За 24 ч ничего",
  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "Ни в названиях заметок, ни в папках, ни в тексте, и ничего похожего по написанию. Попробуйте меньше букв, другое написание или слово из самой заметки.",
  "Nothing in the last 24 hours. What your AIs do shows up here as it happens.": "За последние 24 часа ничего нет. Всё, что делают ваши ИИ, появится здесь по мере действий.",
  "Nothing in the log goes by “{name}”. Showing all activity.": "В журнале нет записей по «{name}». Показана вся активность.",
  "Nothing in this range": "В этот период ничего нет",
