  "Nothing is allowed. Turn something on, or pause the agent instead.": "Ничего не разрешено. Включите что-нибудь или лучше приостановите агента.",
  "Nothing is lost: the current text stays in the history as v{n}, so you can switch back at any time.": "Ничего не потеряется: текущий текст останется в истории как v{n}, так что вернуться можно в любой момент.",
