  "Some apps only load a new connection after a restart. Quit {app} fully and open it again.": "Некоторые приложения подхватывают новое подключение только после перезапуска. Полностью закройте {app} и откройте снова.",
  "Someone else changed this note while you were editing. Choose which version to keep before you leave.": "Кто-то другой изменил эту заметку, пока вы её редактировали. Выберите, какую версию оставить, прежде чем уйти.",
