  "Subfolders are kept inside the destination and links to the moved notes are updated. If a name is already taken there, a number is added to it.": "Подпапки сохраняются внутри места назначения, а ссылки на перемещённые заметки обновляются. Если имя там уже занято, к нему добавляется номер.",
