  "Switch tools for": "Переключить инструменты для",
  "Switch tools off for Mnemo or for its sub-agents, and keep notes, folders or pictures private from it.": "Отключайте инструменты для Mnemo или его субагентов и скрывайте от него заметки, папки или картинки.",
  "Switch tools on or off for everyone and change any agent's key and access, its own included.": "Включайте и отключайте инструменты для всех и меняйте ключ и доступ любого агента, включая свой.",
