  "Tell Mnemo about you": "Расскажите Mnemo о себе",
  "Tell {mnemo} about you": "Расскажите {mnemo} о себе",
  "Tell {mnemo} how you like things, in your own words: the language to answer in, how to name notes, folders to leave alone…": "Расскажите {mnemo}, как вам нравится, своими словами: на каком языке отвечать, как называть заметки, какие папки не трогать…",
  "Test": "Проверить",
  "Test an address": "Проверить адрес",
