  "This server is run by systemd, which starts it again a few seconds later. To keep it stopped, run {cmd} on the server instead.": "Этот сервер запускается через systemd, который через несколько секунд запустит его снова. Чтобы он оставался остановленным, выполните на сервере {cmd}.",
  "This server runs in Docker, which may start it again. To keep it stopped, run {cmd} on the host instead.": "Этот сервер работает в Docker, который может запустить его снова. Чтобы он оставался остановленным, выполните на хосте {cmd}.",
  "This vault has no tags yet. Add {inline} or a {line} line to a note.": "В этом хранилище пока нет тегов. Добавьте {inline} или строку {line} в заметку.",
