  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "{mnemo} работает только в ваших заметках. Каждое изменение видно в Активности и может быть отменено через Историю.",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "{mnemo} читает ваше хранилище в новом чате и сохраняет здесь то, что узнаёт.",
  "{mnemo} settings saved": "Настройки {mnemo} сохранены",
  "{mnemo} settings: models and keys": "Настройки {mnemo}: модели и ключи",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "{mnemo} сам запускает субагентов, когда задача хорошо делится; настраивать ничего не нужно. Они работают на вашей модели по умолчанию, затем на запасных, если вы не укажете модель в чате. Следите за ними и меняйте их модель в «Агентах» справа вверху чата. Они тратят собственные токены, поэтому в режиме «Сначала спрашивать» {mnemo} спрашивает и называет примерное число; в режиме «Авто» они просто запускаются. Сохраняется сразу.",
