  "{mnemo}'s own ({n})": "Собственные подсказки {mnemo} ({n})",
  "{mnemo}'s own notes on how to talk to you, read in every chat. Click one to change it.": "Собственные заметки {mnemo} о том, как с вами общаться; читаются в каждом чате. Нажмите на одну, чтобы изменить.",
  "{mnemo}, your notes agent": "{mnemo}, ваш агент заметок",
  "{mnemo}: {text}": "{mnemo}: {text}",
  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} не умеет смотреть изображения; вместо них получила их названия. Задайте в Настройках модель, которая читает изображения, чтобы их видели.",
  "{model} cannot look at images; the image model described them for it.": "{model} не умеет смотреть изображения; модель для изображений описала их для неё.",
  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} не умеет читать картинки, поэтому получает только их названия. Задайте модель, которая читает изображения, или смените модель этого чата.",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} не умеет читать картинки, поэтому получила только их названия. Задайте модель, которая читает изображения, или смените модель этого чата.",
  "{model} cannot read pictures, so the image model looked at them for it.": "{model} не умеет читать картинки, поэтому модель для изображений посмотрела их за неё.",
  "{model} cannot read pictures, so the image model looks at them for it.": "{model} не умеет читать картинки, поэтому модель для изображений смотрит их за неё.",
  "{model} did not answer ({why}); trying again in {wait} s ({n}/{total})…": "{model} не ответила ({why}); повтор через {wait} с ({n}/{total})…",
